          ],
          "why_it_matters": "本节点讲授权实质条件，三性是贯穿全章的判定主线，必须先立住条文。"
        },
        "chosen_by": "[B]",
        "trigger": "mandatory",
        "rationale": "法条溯源，确保内容准确性",
        "adapts_to": [
          "sequential"
        ],
