        "block_type": "worked_example",
        "title": "案例演示",
        "payload": {
          "problem": "甲公司2024年5月1日在政府主办国际展会展出新型纳米材料专利相关论文，2024年10月1日提出专利申请。问：展出是否破坏新颖性？",
          "applicable_rule": "《专利法》第24条（不丧失新颖性宽限期6个月）",
          "steps": [
            {
              "reasoning": "展出日在申请日前，且属政府主办国际展会法定情形",
              "summary": "落入宽限期适用范围"
            },
            {
              "reasoning": "申请日2024-10-01距展出日2024-05-01约5个月<6个月",
              "summary": "在宽限期内"
            },
            {
              "reasoning": "宽限期仅豁免该公开，不改变三性实质审查",
              "summary": "仍需过创造性/实用性"
            }
          ],
          "conclusion": "展出不破坏新颖性，但仅豁免该次公开，实体三性仍须满足。",
          "takeaway": "宽限期是‘时间豁免’不是‘免死金牌’，先判范围再算日期。"
        },
        "chosen_by": "[B]",
        "trigger": "cognition.apply=0.34<0.4 / cognition.analyze=0.27<0.3 / cold_start",
        "rationale": "演示如何将规则套入具体案情",
        "adapts_to": [
