            {
              "condition": "公开日在申请日之后",
              "outcome": "不可能破坏（尚未公开）"
            },
            {
              "condition": "公开日在申请日前且属宽限期情形且在6个月内申请",
              "outcome": "不破坏"
            },
            {
              "condition": "公开日在申请日前且不属于宽限期或超期",
              "outcome": "构成现有技术，破坏新颖性"
            }
          ],
