          "mapping": [
            {
              "term": "新",
              "explanation": "新颖性=申请日前未公开（含宽限期例外）"
            },
            {
              "term": "创",
              "explanation": "创造性=对本领域普通技术人员非显而易见"
            },
            {
              "term": "实",
              "explanation": "实用性=能制造使用并产生积极效果"
            }
          ],
          "when_recall": "看到‘授权条件’‘为什么不给专利’时先过三性表。"
        },
        "chosen_by": "[B]",
        "trigger": "remember=0.82>=0.6 & apply<0.4 / understanding=sequential(0.75)",
